import { getLandingPageUrls, makeNewLandingPage } from '@common/utils/landing-page';
import { mapContentComponentState } from '@common/utils/layout';
import { PositioningType } from '@common/utils/positioning';
import { raiseBrowserAnalytics } from '@common/utils/usage-register';
import { getOFWindow } from '@common/utils/window';
import { saveWorkspaceInternal } from '@common/utils/workspace';
import { showDeleteWorkspaceModal } from '@common/utils/workspace-modals';
import { showDeletePageModal } from '@common/utils/workspace-modals';

import { t } from '@common/api/i18next';
