import { getCurrentSync } from '..';

export const saveWorkspaceHandlerWithInjectables = async ({
    showModal,
    afterSuccessSave
}: {
    showModal?: () => Promise<void>;
    afterSuccessSave?: () => Promise<void>;
}) => {
    const platform = getCurrentSync();
    const activeWorkspace = await platform.getCurrentWorkspace();
    const savedWorkspaces = await platform.Storage.getWorkspacesMetadata();
    const activeWorkspaceId = activeWorkspace.workspaceId;

    const workspaceExists = savedWorkspaces.some((workspace) => workspace.workspaceId === activeWorkspaceId);
    if (workspaceExists) {
        await saveWorkspaceInternal(activeWorkspace, platform);
        await platform.setActiveWorkspace(activeWorkspace);
        await afterSuccessSave();
    } else {
        await showModal();
    }
};

export const saveWorkspaceHandler = async (identity: OpenFin.Identity) => {
    const platform = getCurrentSync();
    await saveWorkspaceHandlerWithInjectables({
        showModal: async () => {
            const browser = platform.Browser.wrapSync(identity);
            // eslint-disable-next-line no-underscore-dangle
            await browser._openSaveModal({
                menuType: SaveModalType.SAVE_WORKSPACE_AS
            });
        },
        afterSuccessSave: async () => {
            await showWorkspaceSavedSuccess({
                message: t('successIndicator.workspaceSaved'),
                parentBrowserName: identity.name
            });
        }
    });
};

export const saveWorkspaceAsHandler = (identity: OpenFin.Identity) => {
    const browserWin = getCurrentSync().Browser.wrapSync(identity);
    // eslint-disable-next-line no-underscore-dangle
    browserWin._openSaveModal({
        menuType: SaveModalType.SAVE_WORKSPACE_AS
    });
};

/**
 * @param identity Identity of browser window to create a new page on.
 */
export const createNewPageHandler = async (identity: OpenFin.Identity) => {
    const browser = getCurrentSync().Browser.wrapSync(identity);
    const { newPageUrl } = await getLandingPageUrls();
    const newPage = await makeNewLandingPage(identity);
    const actualNewPageUrl = newPageUrl ? newPageUrl : undefined;
    // eslint-disable-next-line no-underscore-dangle
    await browser._addDefaultPage({ identity: identity, page: newPage, newPageUrl: actualNewPageUrl });
};

/**
 * @param identity Identity of browser window to execute save on.
 * @param pageId Id of a page to save. If omitted, active page is saved.
 */
export const savePageHandler = async (identity: OpenFin.Identity, pageId?: string) => {
    const platform = getCurrentSync();
    const browserWin = platform.Browser.wrapSync(identity);
    const allSavedPages = await getCurrentSync().Storage.getPages();
    const allPages = await browserWin.getPages();
    const pageToSave = allPages.find((page) => (pageId ? page.pageId === pageId : page.isActive));
    const pageSavedPreviously = allSavedPages.some((page) => pageToSave.pageId === page.pageId);
    const isEnterprise = await isEnterpriseBrowser(identity);

    if (pageSavedPreviously) {
        try {
            await getCurrentSync().Storage.savePage(cleanPage(pageToSave)); // Updates title but NOT hasUnsavedChanges
            await browserWin.updatePage({
                pageId: pageToSave.pageId,
                page: {
                    hasUnsavedChanges: false
                }
            });
            showSuccess({
                message: isEnterprise ? t('enterpriseSuccessIndicator.supertabSaved') : t('successIndicator.pageSaved'),
                parentBrowserName: identity.name,
                secondaryMessage: isEnterprise
                    ? t('enterpriseSuccessIndicator.supertabHasBeenSaved', { title: pageToSave.title })
                    : t('successIndicator.pageHasBeenSaved', { title: pageToSave.title }),
                isEnterprise
            });
        } catch {
            showError({
                message: t('errorIndicator.pageSaveFailed'),
                parentBrowserName: pageToSave.parentIdentity.name
            });
        }
    } else {
        // eslint-disable-next-line no-underscore-dangle
        browserWin._openSaveModal({
            id: pageToSave.pageId,
            menuType: SaveModalType.SAVE_PAGE
        });
    }
};

/**
 * @param identity Identity of browser window to execute save on.
 * @param pageId Id of a page to save. If omitted, active page is saved.
 */
export const savePageAsHandler = async (identity: OpenFin.Identity, pageId?: string) => {
    const platform = getCurrentSync();
    const browserWin = platform.Browser.wrapSync(identity);
    const allPages = await browserWin.getPages();
    const pageToSave = allPages.find((page) => (pageId ? page.pageId === pageId : page.isActive));
    // eslint-disable-next-line no-underscore-dangle
    browserWin._openSaveModal({
        id: pageToSave.pageId,
        menuType: SaveModalType.SAVE_PAGE_AS
    });

    raiseBrowserAnalytics({
        type: 'Page Modal',
        action: 'Select Save As',
        value: pageToSave.title,
        skipValueHashing: true
    });
};

export const switchWorkspaceHandler = async (
    winIdentity: OpenFin.Identity,
    workspaceItemData: WorkspaceContextMenuItemData
) => {
    const platform = getCurrentSync();
    const savedWorkspaces = await platform.Storage.getWorkspaces();
    const selectedWorkspace = savedWorkspaces.find(
        (workspace) => workspace.workspaceId === workspaceItemData.workspaceId
    );

    platform.applyWorkspace(selectedWorkspace, {
        skipPrompt: false,
        promptContainerWindowIdentity: winIdentity
    });
};

export const deleteWorkspaceHandlerWithPayload = async ({
    workspaceItemData,
    winIdentity,
    positioning
}: {
    workspaceItemData: WorkspaceContextMenuItemData;
    winIdentity?: OpenFin.Identity;
    positioning?: PositioningType;
}) => {
    const platform = getCurrentSync();
    const savedWorkspaces = await platform.Storage.getWorkspacesMetadata();
    const targetWorkspace = savedWorkspaces.find(
        (workspace) => workspace.workspaceId === workspaceItemData.workspaceId
    );
    if (targetWorkspace) {
        const shouldDelete = await showDeleteWorkspaceModal({
            workspaceTitle: targetWorkspace.title,
            windowIdentity: winIdentity
        });
        if (shouldDelete) {
            await platform.Storage.deleteWorkspace(workspaceItemData.workspaceId);
            await showSuccess({
                message: t('successIndicator.workspaceDeleted'),
                parentBrowserName: winIdentity?.name,
                positioning
            });
        }
    }
};

export const deleteWorkspaceHandler = async (
    winIdentity: OpenFin.Identity,
    workspaceItemData: WorkspaceContextMenuItemData
) => {
    await deleteWorkspaceHandlerWithPayload({
        workspaceItemData,
        winIdentity
    });
};

const downloadPage = {
    title: 'Downloads',
    pageId: 'downloads-page-id',
    layout: {
        content: [
            {
                type: 'stack',
                content: [
                    {
                        type: 'component',
                        componentName: 'view',
                        componentState: {
                            name: 'show-download-view',
                            url: 'chrome://downloads/'
                        }
                    }
                ]
            }
        ]
    }
};

export const downloadsHandler = async (identity: OpenFin.Identity) => {
    const win = getOFWindow(identity);
    const views = await win.getCurrentViews();
    const activePage = (await getCurrentSync().Browser.wrapSync(win.identity).getPages()).find((p) => p.isActive);

    try {
        const allViewsWithInfoResolved = await Promise.all(
            views.map(async (view) => ({
                identity: view.identity,
                info: await fin.View.wrapSync(view.identity).getInfo()
            }))
        );

        const currentDownloadView = allViewsWithInfoResolved.find((view) => view.info.url === 'chrome://downloads/');

        if (currentDownloadView) {
            await fin.View.wrapSync(currentDownloadView.identity).focus();
        } else {
            const platform = getCurrentSync();
            if (activePage?.isLocked) {
                const allWindows = await fin.Application.getCurrentSync().getChildWindows();
                const foundDownloadWindow = allWindows.find(
                    (window) => window.identity.name === 'show-download-window'
                );

                if (foundDownloadWindow) {
                    await foundDownloadWindow.focus();
                } else {
                    platform.Browser.createWindow({
                        name: 'show-download-window',
                        workspacePlatform: {
                            pages: [downloadPage]
                        }
                    });
                }
                return;
            }

            const view = await WorkspacePlatform.getCurrentSync().createView(
                { name: 'show-download-view', url: 'chrome://downloads/', target: identity },
                identity
            );
            view.focus();
        }
    } catch (error) {
        console.error("Couldn't open downloads view", error);
    }
};

/**
 * Reload activ view
 * Enterprise Browser
 * @param identity
 * @param pageId
 */
export const reloadPageHandler = async (identity: OpenFin.Identity, pageId?: string) => {
    const platform = getCurrentSync();
    const browserWin = platform.Browser.wrapSync(identity);
    const allPages = await browserWin.getPages();
    const activePage = allPages.find((page) => (pageId ? page.pageId === pageId : page.isActive));
    if (activePage?.layout?.content) {
        const views = mapContentComponentState(activePage.layout.content);
        views.forEach(async (componentState) => {
            const view = await fin.View.wrap({
                uuid: platform.identity.uuid,
                name: componentState.name
            });
            view.reload();
        });
    }
};

/**
 * Close page, without Save Modal
 * Enterprise Browser
 * @param identity
 * @param pageId
 */
export const closePageHandler = async (identity: OpenFin.Identity, pageId?: string) => {
    const platform = getCurrentSync();
    const browserWin = platform.Browser.wrapSync(identity);
    const allPages = await browserWin.getPages();
    for (const page of allPages) {
        if (page.pageId === pageId) {
            await browserWin.removePage(page.pageId);
            // eslint-disable-next-line no-underscore-dangle
            await browserWin._trackRemovedTab({ identity: identity, page });
            break;
        }
    }
};

/**
 * Close other pages
 * Enterprise Browser
 * @param identity
 * @param pageId
 */
export const closeOtherPagesHandler = async (identity: OpenFin.Identity, pageId?: string) => {
    const platform = getCurrentSync();
    const browserWin = platform.Browser.wrapSync(identity);
    const allPages = await browserWin.getPages();
    for (const page of allPages) {
        if (page.pageId !== pageId) {
            await browserWin.removePage(page.pageId);
            // eslint-disable-next-line no-underscore-dangle
            await browserWin._trackRemovedTab({ identity: identity, page });
        }
    }
};

/**
 * @param viewIdentities Array of views to execute print on.
 */
export const printSelectedViews = async (viewIdentities: OpenFin.Identity[]) => {
    const printViewPromises = viewIdentities.map((identity) => {
        const view = fin.View.wrapSync(identity);
        return view.print();
    });
    await Promise.all(printViewPromises);
};

export const deletePageHandler = async (identity: OpenFin.Identity, pageId?: string) => {
    const platform = getCurrentSync();
    const browser = platform.Browser.wrapSync(identity);
    const savedPages = await platform.Storage.getPages();
    const targetPage = savedPages.find((page) => page.pageId === pageId);
    if (targetPage) {
        const shouldDelete = await showDeletePageModal(identity, targetPage.title);
        if (shouldDelete) {
            await platform.Storage.deletePage(targetPage.pageId);
            await browser.removePage(pageId);
            showSuccess({
                message: t('enterpriseSuccessIndicator.supertabDeleted'),
                parentBrowserName: identity.name,
                secondaryMessage: t('enterpriseSuccessIndicator.supertabHasBeenDeleted', { title: targetPage.title })
            });
        }
    }
};
