import { useContext } from 'react';

import Route from '@common/utils/route';
import { WindowName } from '@common/utils/window';

import { BrowserTypeContext } from '@common/hooks/context';
import usePreloadedWindow from '@common/hooks/usePreloadedWindow';

export const useEnterpriseContextMenu = () =>
    usePreloadedWindow({
        windowName: WindowName.EnterpriseContextMenu,
        route: Route.EnterpriseContextMenu,
        shouldPreload: useContext(BrowserTypeContext).isEnterprise,
        windowCreationOptions: {
            defaultWidth: 10,
            defaultHeight: 10,
            shadow: true
        }
    });

export default useEnterpriseContextMenu;
