import { useEffect, useState } from 'react';

import { isFin } from '@common/utils/env';

import {
    addEventListener,
    getNotificationsCount,
    NotificationsCountChanged,
    removeEventListener
} from '@client/notifications';
import * as Notifications from '@openfin/notifications';

import useIsNotificationsRunning from './useIsNotificationsRunning';

/**
 * useNotificationsCount Hook
 * @param lastFetch new Date() will rerun the hook and update the count
 * @returns number
 */
export default function useNotificationsCount(lastFetch?: Date): number {
    const [notificationCount, setNotificationCount] = useState(0);
    const isNotificationsRunning = useIsNotificationsRunning();
    const listener = ({ count }: NotificationsCountChanged) => {
        setNotificationCount(count);
    };
    useEffect(() => {
        if (isFin) {
            const updateNotificationsCount = async () => {
                if (!isNotificationsRunning) {
                    setNotificationCount(0);
                    return;
                }

                const initCountListener = async () => {
                    // should only get here if notifications is already running -this call ensures that the channel is setup
                    await Notifications.register();
                    // Ensure that we remove any existing listeners in the client to get the client and provider in sync
                    await removeEventListener('notifications-count-changed', listener);
                    // Listen for new notifications events
                    await addEventListener('notifications-count-changed', listener);
                    // Set the initial notifications count
                    const count = await getNotificationsCount();
                    setNotificationCount(count);
                };

                try {
                    await initCountListener();
                } catch (e) {
                    console.debug('Notifications Count Error:', e);
                }
            };
            updateNotificationsCount();

            return () => {
                removeEventListener?.('notifications-count-changed', listener).catch((e) => {
                    console.debug('notifications not running', e);
                });
            };
        }
    }, [lastFetch, isNotificationsRunning]);

    return notificationCount;
}
