import { registerNotificationUsage } from '@common/utils/usage-register';

import { getSyncChannelName, NOTIFICATIONS_SYNC_CHANNEL } from '@common/api/protocol/notifications';
import {
    getWorkspacePlatformChannelClient,
    WorkspacePlatformChannelAction
} from '@common/api/protocol/workspace-platform';

import * as Notifications from '@openfin/notifications';

import type { NotificationsPlatform, NotificationsRegisterOptions } from './shapes/notifications';

export * from '@openfin/notifications';
export * from './shapes/notifications';

const getErrorMessage = async (error: unknown) => {
    if (error instanceof Error) {
        let errorMessage = error.message;
        if (error.message.includes('register-notifications-platform')) {
            errorMessage =
                'Notifications platforms are not supported in versions below 1.13.0, try updating your notifications-service.';
            if (Notifications?.provider?.getStatus) {
                const { version } = await Notifications.provider.getStatus();
                errorMessage += ` Your version is: ${version}`;
            }
            return errorMessage;
        }
        return error.message;
    }

    if (typeof error === 'string') {
        return error;
    }

    return 'unknown error registering Notifications';
};

const handlerError = async (error: unknown) => {
    if (error instanceof Error && error.message.includes('register-notifications-platform')) {
        throw new Error(await getErrorMessage(error));
    }
    throw error;
};

const SERVICE_CHANNEL = 'of-notifications-service-v1';

/**
 * Notifications Center <= 2.13 expects a legacy NotificationsThemeSet object.
 * Versions >= 2.14 supports detailed theming.
 */
export const isLegacyNotifications = (version: string): boolean => {
    const [major, minor] = version.split('.').map(Number);
    return major < 2 || (major === 2 && minor <= 13);
};

type SyncChannelConfig = {
    channelName: string;
};

const syncChannelConfig: SyncChannelConfig = {
    channelName: NOTIFICATIONS_SYNC_CHANNEL // default to OF hosted service
};

const registerPlatform = async (
    platform: Partial<Notifications.PlatformRegisterPayload>,
    opts: { notificationsVersion: string },
    wait = false
): Promise<void> => {
    const channelName = opts.notificationsVersion.startsWith('2') ? syncChannelConfig.channelName : SERVICE_CHANNEL;
    const channelClient = await fin.InterApplicationBus.Channel.connect(channelName, {
        wait
    });
    const registerAction = opts.notificationsVersion.startsWith('2')
        ? 'register-platform'
        : 'register-notifications-platform';
    await channelClient.dispatch(registerAction, platform);
};

const deregisterPlatform = async (
    platform: Partial<Notifications.PlatformDeregisterPayload>,
    opts: { notificationsVersion: string }
): Promise<void> => {
    // FIX ME: this check will fail as soon as we release a NC v3.
    const channelName = opts.notificationsVersion.startsWith('2') ? syncChannelConfig.channelName : SERVICE_CHANNEL;
    const channelClient = await fin.InterApplicationBus.Channel.connect(channelName, {
        wait: false
    });
    const deregisterAction = opts.notificationsVersion.startsWith('2')
        ? 'deregister-platform'
        : 'deregister-notifications-platform';
    await channelClient.dispatch(deregisterAction, platform);
};

/**
 * @deprecated Use `register` with {@link NotificationsRegisterOptions | options?: NotificationsRegisterOptions} argument instead.
 */
export async function register(platform: NotificationsPlatform): Promise<Notifications.NotificationsRegistration>;

/**
 * Launches Notifications service and registers a notifications platform. Throws if workspace platform is not initialized or if you run version of notifications-service which doesn't support platforms.
 *
 * @param options {@link NotificationsPlatform} object
 */
export async function register(
    options?: NotificationsRegisterOptions
): Promise<Notifications.NotificationsRegistration>;

export async function register(opts?: unknown): Promise<Notifications.NotificationsRegistration> {
    try {
        const syncChannel = await getSyncChannelName();

        const config =
            opts && 'notificationsCustomManifest' in (opts as NotificationsRegisterOptions)
                ? { customManifest: (opts as NotificationsRegisterOptions).notificationsCustomManifest }
                : undefined;

        let wait = false;

        if (syncChannel !== NOTIFICATIONS_SYNC_CHANNEL) {
            syncChannelConfig.channelName = syncChannel;
            wait = true;
        } else {
            if (config && config.customManifest?.manifestUuid) {
                syncChannelConfig.channelName = `${config.customManifest.manifestUuid}-${NOTIFICATIONS_SYNC_CHANNEL}`;
                console.warn(
                    "Using 'notificationsCustomManifest' is deprecated. Please include custom manifest in platform manifest."
                );
            }
        }
        const notificationsRegistration = await Notifications.register(config);

        const client = await getWorkspacePlatformChannelClient(fin.me.identity);
        const themePaletteSheet: string = await client.dispatch(
            WorkspacePlatformChannelAction.GetThemePaletteSheet,
            undefined
        );
        const notificationsIndicatorColors = await client.dispatch(
            WorkspacePlatformChannelAction.GetNotificationIndicatorColorsInternal,
            undefined
        );

        // If platform options are provided, need to register platform
        if (opts) {
            const scheme = await client.dispatch(WorkspacePlatformChannelAction.GetSelectedScheme, undefined);
            const isLegacy = isLegacyNotifications(notificationsRegistration.notificationsVersion);

            // For old notifications (<=2.13): send legacy theme object
            // For new notifications (>=2.14): send theme palette sheet
            const legacyTheme = isLegacy
                ? await client.dispatch(WorkspacePlatformChannelAction.GetLegacyNotificationsThemeInternal, undefined)
                : null;

            const notificationsPlatformOpts =
                'notificationsPlatformOptions' in (opts as NotificationsRegisterOptions)
                    ? (opts as NotificationsRegisterOptions).notificationsPlatformOptions
                    : (opts as NotificationsPlatform);

            // The legacy theme object structurally matches NotificationsThemeSet (which
            // isn't exported from @openfin/notifications), so we cast through unknown.
            const themePayload = legacyTheme ?? themePaletteSheet;

            await registerPlatform(
                {
                    // Legacy notifications embed indicator colors inside the theme object;
                    // new notifications receive them as a separate top-level property.
                    theme: themePayload as unknown as string,
                    ...(isLegacy ? {} : { notificationsIndicatorColors }),
                    scheme,
                    ...notificationsPlatformOpts,
                    workspacePlatform: {
                        identity: fin.Platform.getCurrentSync().identity,
                        analytics: {
                            isSupported: true
                        }
                    }
                },
                { notificationsVersion: notificationsRegistration.notificationsVersion },
                wait
            );
        }

        registerNotificationUsage({
            allowed: true,
            apiVersion: Notifications.VERSION,
            componentVersion: notificationsRegistration.notificationsVersion
        });

        return notificationsRegistration;
    } catch (err) {
        registerNotificationUsage({
            allowed: false,
            rejectionCode: await getErrorMessage(err),
            apiVersion: Notifications.VERSION
        });

        await handlerError(err);
    }
}

/**
 * Deregisters notifications platform. Throws if you run version of notifications-service which doesn't support platforms.
 * @param platformId id of the platform to deregister
 */
export const deregister = async (platformId: string): Promise<void> => {
    try {
        const { version } = await Notifications.provider.getStatus();
        if (version === null) {
            throw new Error('Notifications service is not currently running.');
        }
        await deregisterPlatform({ id: platformId }, { notificationsVersion: version });
    } catch (err) {
        await handlerError(err);
    }
};
