import styled from 'styled-components';

export const VisuallyHidden = styled.div`
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    height: 1px;
    overflow: hidden;
    position: absolute;
    white-space: nowrap;
    width: 1px;
`;

// This styled component wraps ControlBar buttons so they're still interactable
export const NoDragWrapper = styled.div`
    -webkit-app-region: no-drag;
    user-select: auto;
`;
