import type OpenFin from '@openfin/core';

const oneHourInMillis = 60 * 60 * 1000;
const lastEmitTimes = new Map<string, number>();
// eslint-disable-next-line no-underscore-dangle
let _channel: OpenFin.ChannelClient | undefined;

const getChannel = async () => {
    if (!_channel) {
        _channel = await fin.InterApplicationBus.Channel.connect(
            `${fin.me.identity.uuid}-enterprise-google-analytics`,
            { wait: false }
        );
    }

    return _channel;
};

const sendGAEvent = async ({ name, payload }: { name: string; payload?: Record<string, unknown> }) => {
    const channel = await getChannel();

    await channel.dispatch('send-analytics-event', { name, payload });
};

export const sendGAEventWithThrottle = async ({
    name,
    payload,
    delay = oneHourInMillis
}: {
    name: string;
    payload?: Record<string, unknown>;
    delay?: number;
}) => {
    try {
        const now = Date.now();

        if (now - (lastEmitTimes.get(name) ?? 0) > delay) {
            await sendGAEvent({ name, payload });

            lastEmitTimes.set(name, now);
        }
    } catch (error) {
        // Ignore errors as we don't want to block the application
    }
};
