import { useCallback, useEffect } from 'react';

import { getAbsoluteRoutePath } from '@common/utils/router';

export interface ThemedTaskbarIconProps {
    light: string;
    dark: string;
    custom: boolean;
}

export const useUpdateTaskbarIcon = (iconData: ThemedTaskbarIconProps | undefined) => {
    const updateIcon = useCallback(
        async (event: MediaQueryListEvent | MediaQueryList) => {
            if (!iconData) {
                return;
            }

            try {
                await fin.me.updateOptions(
                    event.matches
                        ? { icon: iconData.custom ? iconData.dark : getAbsoluteRoutePath(iconData.dark) }
                        : { icon: iconData.custom ? iconData.light : getAbsoluteRoutePath(iconData.light) }
                );
            } catch (error) {
                console.error('Failed to update taskbar icon', error);
            }
        },
        [iconData]
    );

    useEffect(() => {
        const colorModePreference = window.matchMedia('(prefers-color-scheme: dark)');

        updateIcon(colorModePreference);
        colorModePreference.addEventListener('change', updateIcon);
        return () => {
            colorModePreference.removeEventListener('change', updateIcon);
        };
    }, [updateIcon, iconData]);
};
