import { emit } from '@common/api/workspace-events';

import * as notificationsAPI from '@client/notifications';

/**
 * Shows the Notification Center and navigates to "All" section.  NOTE: emits a workspace event
 */
export async function navigateToAllNotificationCenter() {
    try {
        console.debug('requesting notifications show');
        await notificationsAPI.show({ navigateToAll: true });
    } catch (err) {
        if (err instanceof Error && err.message === 'No action registered at target for show-notification-center') {
            // An older version of notifications center is running, falling back to using the toggle method
            console.warn(
                'The Notifications `show` API method is not available, falling back to `toggle`. Consider updating the Notifications Center Version.'
            );
            try {
                await notificationsAPI.toggleNotificationCenter();
            } catch (e) {
                emit('update-notification-running-status');
                console.debug('error showing notification center, notifications may not be running', err);
            }
        } else {
            emit('update-notification-running-status');
            console.debug('error showing notification center, notifications may not be running', err);
        }
    }
}

export async function toggleNotificationCenter() {
    try {
        console.debug('requesting notification toggle');
        const { toggleNotificationCenter: toggle } = notificationsAPI;
        await toggle();
    } catch (err) {
        emit('update-notification-running-status');
        console.debug('error toggling notification center, notifications may not be running', err);
    }
}
