import { useEffect, useRef, useState } from 'react';

import type OpenFin from '@openfin/core';

import { isFin } from '@common/utils/env';
import { notificationCenterOFIdentity } from '@common/utils/window';

import { getNotificationCenterUuid } from '@common/api/protocol/notifications';
import { addListener, removeListener } from '@common/api/workspace-events';

const log = (message: string, ...args: unknown[]) => console.debug(`[useIsNotificationsRunning] ${message}`, ...args);

/**
 * useIsNotificationsRunning Hook
 * @returns boolean
 */
export default function useIsNotificationsRunning(): boolean {
    const [isNotificationsRunning, setIsNotificationsRunning] = useState(false);
    const notificationCenterIdentityRef = useRef<OpenFin.Identity>(notificationCenterOFIdentity);

    useEffect(() => {
        if (isFin) {
            const initializeState = async () => {
                const uuid = await getNotificationCenterUuid();
                log('Retrieved Notification Center UUID:', uuid);
                const ncIdentity = { ...notificationCenterOFIdentity, uuid };
                notificationCenterIdentityRef.current = ncIdentity;
                log('Notification Center Identity Set To:', ncIdentity);
                const app = fin.Application.wrapSync(ncIdentity);
                const isRunning = await app.isRunning();
                if (isRunning) {
                    log('Notification Center is running.');
                    setIsNotificationsRunning(true);
                } else {
                    log('Notification Center is not running.');
                    setIsNotificationsRunning(false);
                }
            };
            addListener('update-notification-running-status', initializeState);

            const updateIsRunningStatus = (payload: OpenFin.SystemEvent & { uuid: string }): void => {
                log(
                    `Lifecycle event ${payload.type} received, current Notification Center Identity:`,
                    notificationCenterIdentityRef.current
                );
                if (payload.uuid === notificationCenterIdentityRef.current.uuid) {
                    if (payload.type === 'application-started') {
                        log(`Setting isNotificationsRunning to true`);
                        setIsNotificationsRunning(true);
                    } else if (payload.type === 'application-closed' || payload.type === 'application-crashed') {
                        log(`Setting isNotificationsRunning to false`);
                        setIsNotificationsRunning(false);
                    }
                }
            };
            const setupNotificationsRunningState = async () => {
                // TODO: This due to CORE-988 bug, when fixed use app events
                await fin.System.on('application-started', updateIsRunningStatus);
                await fin.System.on('application-closed', updateIsRunningStatus);
                await fin.System.on('application-crashed', updateIsRunningStatus);
                initializeState();
            };
            setupNotificationsRunningState();

            return () => {
                fin.System.removeListener('application-started', updateIsRunningStatus);
                fin.System.removeListener('application-closed', updateIsRunningStatus);
                fin.System.removeListener('application-crashed', updateIsRunningStatus);
                removeListener('update-notification-running-status', initializeState);
            };
        }
    }, []);

    return isNotificationsRunning;
}
